/* Notes for s34 — generated by tools/build-notes.js from content/notes. Do not edit by hand. */
PG.notes("l265", "<p class=\"summary\">Brief for the Book Notes capstone: build an Express + PostgreSQL + EJS site that records books you have read, with covers from the Open Library Covers API. This is an instructions page (opened via an Open button, no video transcript), so the notes come from the brief and the reference repo.</p>\n<h3>Project idea</h3>\n<ul><li>A personal reading-notes site: each book has a title, author, rating, review text, date read and an ISBN. The model is a public book-notes site by Derek Sivers, where the list can be sorted by rating, recency or title.</li><li>The stated learning goals are: revisit consuming public APIs, get more server-side practice with Express/Node, and show full Create/Read/Update/Delete against PostgreSQL.</li></ul>\n<h3>Requirements checklist</h3>\n<ul><li>Persistence: store data in PostgreSQL and manipulate it with CRUD queries.</li><li>Planning: study the API docs first, decide what data to store, sketch the database diagram (draw.io) and plan the CREATE TABLE statement before coding.</li><li>Setup: Node + Express project, the pg package for the local database, EJS templates, an HTML/CSS/JS frontend, and a tidy folder structure.</li><li>API integration: at least one GET request to the chosen API through Axios, with the response handled.</li><li>Presentation: show covers and database fields in a friendly layout using EJS; think about how users will choose a sort order.</li><li>Error handling: handle failures from both the app/database and the API request; logging to the console is acceptable, user-facing messages are a bonus.</li><li>Documentation: comment the logic; include a README explaining how to start the server (npm i, then nodemon index.js).</li><li>Sharing: commit and push to GitHub so others can view it.</li></ul>\n<h3>Open Library Covers API</h3>\n<ul><li>Covers are fetched by identifier, and the ISBN stored in the database is the natural key, so the page can build an image URL from each book's ISBN (e.g. https://covers.openlibrary.org/b/isbn/&lt;ISBN&gt;-M.jpg, sizes S/M/L).</li><li><span class=\"extra\">Extra:</span> An img tag can point at that URL directly; Axios is only needed if you want to check the cover exists or fetch metadata server-side.</li></ul>\n<h3>Reference implementation (one student's)</h3>\n<ul><li>Routes: GET / (list, optional ?orderBy= query, default date_read DESC), GET /new and POST /new (add), GET /books/:id/edit and POST /books/:id/edit (update), POST /books/:id/delete.</li><li>Uses body-parser urlencoded for form data, express.static for public/, a pg.Client connected to a database called book_notes, and res.redirect('/') after each write.</li><li>Queries are parameterised ($1..$7) for values, which prevents SQL injection for form input.</li><li><span class=\"extra\">Extra:</span> The sort column is interpolated straight into the SQL string from req.query.orderBy, which is injectable; whitelist allowed columns (date_read, rating, title) instead.</li><li><span class=\"extra\">Extra:</span> The repo does not use Axios or the cover API in index.js, so it diverges from the brief's API requirement; the rest of the brief is covered.</li></ul>\n<h2>Code examples</h2>\n<p class=\"caption\">Suggested schema (from the reference repo)</p><pre data-lang=\"sql\">CREATE TABLE books (\n    id SERIAL PRIMARY KEY,\n    title VARCHAR(255) NOT NULL,\n    author VARCHAR(255) NOT NULL,\n    rating INTEGER CHECK (rating &gt;= 1 AND rating &lt;= 10),\n    review TEXT,\n    date_read DATE,\n    isbn VARCHAR(20)\n);</pre>\n<p class=\"caption\">Reference server core (abridged)</p><pre data-lang=\"js\">import express from &quot;express&quot;;\nimport bodyParser from &quot;body-parser&quot;;\nimport pg from &quot;pg&quot;;\n\nconst app = express();\napp.use(bodyParser.urlencoded({ extended: true }));\napp.use(express.static(&quot;public&quot;));\n\nconst db = new pg.Client({ user: &quot;postgres&quot;, host: &quot;localhost&quot;, database: &quot;book_notes&quot;, password: &quot;&lt;your password&gt;&quot;, port: 5432 });\ndb.connect();\n\napp.get(&quot;/&quot;, async (req, res) =&gt; {\n  const orderBy = req.query.orderBy || &quot;date_read&quot;;\n  const result = await db.query(`SELECT * FROM books ORDER BY ${orderBy} DESC`);\n  res.render(&quot;index.ejs&quot;, { books: result.rows });\n});\n\napp.post(&quot;/new&quot;, async (req, res) =&gt; {\n  const { title, author, rating, review, date_read, isbn } = req.body;\n  await db.query(\n    &quot;INSERT INTO books (title, author, rating, review, date_read, isbn) VALUES ($1,$2,$3,$4,$5,$6)&quot;,\n    [title, author, rating, review, date_read, isbn]\n  );\n  res.redirect(&quot;/&quot;);\n});\n// plus GET /new, GET+POST /books/:id/edit (UPDATE ... WHERE id=$7), POST /books/:id/delete (DELETE ... WHERE id=$1)</pre>\n<h2>The task: Capstone: Book Notes</h2>\n<div class=\"task-box\">\n<p><b>Starting point:</b> Empty project; nothing provided apart from the written brief.</p>\n<p><b>Goal:</b> Ship a CRUD web app backed by PostgreSQL that lists books with covers and notes and can be sorted.</p>\n<p><b>Steps</b></p><ol><li>Research the Open Library Covers API and decide the columns to store.</li><li>Draw the database diagram and write the CREATE TABLE statement; create a local database and the table.</li><li>npm init, install express, pg, ejs, axios (and body-parser if on older Express); set up index.js with static folder and views.</li><li>Build the list page showing cover, title, author, rating, date and review, with sort controls (rating, recency, title).</li><li>Add pages/routes to add, edit and delete a book; use parameterised queries.</li><li>Add try/catch around DB and API calls with sensible error messages.</li><li>Comment the code, write the README, push to GitHub.</li></ol>\n<p><b>Expected result:</b> A running site at localhost where books can be added, edited, deleted and sorted, with covers loaded from the API.</p>\n</div>\n<p class=\"caption\">Solution</p><pre data-lang=\"js\">import express from &quot;express&quot;;\nimport bodyParser from &quot;body-parser&quot;;\nimport pg from &quot;pg&quot;;\n\nconst app = express();\napp.use(bodyParser.urlencoded({ extended: true }));\napp.use(express.static(&quot;public&quot;));\n\nconst db = new pg.Client({ user: &quot;postgres&quot;, host: &quot;localhost&quot;, database: &quot;book_notes&quot;, password: &quot;&lt;your password&gt;&quot;, port: 5432 });\ndb.connect();\n\napp.get(&quot;/&quot;, async (req, res) =&gt; {\n  const orderBy = req.query.orderBy || &quot;date_read&quot;;\n  const result = await db.query(`SELECT * FROM books ORDER BY ${orderBy} DESC`);\n  res.render(&quot;index.ejs&quot;, { books: result.rows });\n});\n\napp.post(&quot;/new&quot;, async (req, res) =&gt; {\n  const { title, author, rating, review, date_read, isbn } = req.body;\n  await db.query(\n    &quot;INSERT INTO books (title, author, rating, review, date_read, isbn) VALUES ($1,$2,$3,$4,$5,$6)&quot;,\n    [title, author, rating, review, date_read, isbn]\n  );\n  res.redirect(&quot;/&quot;);\n});\n// plus GET /new, GET+POST /books/:id/edit (UPDATE ... WHERE id=$7), POST /books/:id/delete (DELETE ... WHERE id=$1)</pre>\n<h2>Common mistakes</h2>\n<ul><li>Do not build the ORDER BY clause from raw query-string input; map allowed sort keys to fixed SQL.</li><li>Missing covers return a placeholder or 404 image; handle a fallback image.</li><li>Do not commit your real database password; keep it in config or env vars.</li></ul>");
